import limited_client as robot,numpy as np
from scipy.optimize import least_squares
for i,(x0,x1,y0,y1) in [(0,(150,180,270,310)),(1,(100,145,350,385)),(2,(330,360,255,285))]:
 s=robot.observe(i);im=s['rgb'];r=im[y0:y1,x0:x1];m=(np.max(r,2)-np.min(r,2)<14)&(np.mean(r,2)>60)&(np.mean(r,2)<195);yy,xx=np.where(m);pts=[];Ki=np.linalg.inv(s['intrinsic']);T=s['camera_to_world']
 for y,x in zip(yy+y0,xx+x0):
  d=s['depth_m'][y,x]
  if .2<d<3:pts.append((T@np.r_[Ki@np.array([x,y,1])*d,1])[:3])
 pts=np.array(pts)
 if len(pts)>10:
  sol=least_squares(lambda v:np.linalg.norm(pts-v[:3],axis=1)-v[3],np.r_[np.median(pts,axis=0),.03],loss='soft_l1');print(i,len(pts),sol.x)
